import React, { useState } from 'react';
import { PublicKey, Transaction, Connection, TransactionInstruction, SystemProgram } from '@solana/web3.js';
import { TOKEN_PROGRAM_ID, getAssociatedTokenAddressSync, createAssociatedTokenAccountInstruction } from '@solana/spl-token';
import { toast } from 'react-toastify';
import { LOCK_ICON, ARROW_RIGHT_ICON } from '../utils/constants';
import { PROGRAM_ID, USDC_MINT, DISCRIMINATORS, TRADING_WALLET, FUND_POOL_PDA, REGISTRY_DIRECTORY_PDA } from '../utils/constants';
import { useStyling } from '../hooks/useStyling';
// import { prefindAvailableRegistrySlot } from '../utils/shrub-fund-client';

interface FundTabProps {
  publicKey: PublicKey | null;
  connection: Connection;
  sendTransaction: (tx: Transaction, conn: Connection) => Promise<string>;
  stats: { totalFundValue: number; totalShares: number; nav: number; realNav: number };
  userInfo: { shares: number; shareValue: number; canUnstake: boolean; stakeTimestamp: number; hasPendingUnstake: boolean; pendingUnstakeValue: number };
  balances: { usdc: number };
  loadingStats: boolean;
  loadingUserData: boolean;
  refreshUserData: () => Promise<void>;
}

const FundTab: React.FC<FundTabProps> = ({
  publicKey,
  connection,
  sendTransaction,
  stats,
  userInfo,
  balances,
  loadingUserData,
  refreshUserData,
}) => {
  const styling = useStyling();
  const [fundAmount, setFundAmount] = useState('');
  const [isStaking, setIsStaking] = useState(false);

  const isValidFundAmount = fundAmount && parseFloat(fundAmount) > 0 && parseFloat(fundAmount) <= balances.usdc;

  const handleStakeFund = async () => {
    // If wallet not connected, trigger wallet modal
    if (!publicKey) {
      const walletButton = document.querySelector('.wallet-adapter-button') as HTMLElement;
      if (walletButton) {
        walletButton.click();
      }
      return;
    }

    if (!fundAmount || parseFloat(fundAmount) <= 0) return;

    setIsStaking(true);

    try {
      const amountRaw = Math.floor(parseFloat(fundAmount) * 1_000_000); // USDC has 6 decimals

      // Derive user share PDA, use constants for others to match existing deployment
      const [userSharePda] = PublicKey.findProgramAddressSync(
        [Buffer.from("user_share_v2"), publicKey.toBuffer()], 
        PROGRAM_ID
      );
      // Use the existing fund pool PDA from constants (already deployed with this address)
      const fundPoolPda = FUND_POOL_PDA;

      // Get token accounts
      const userUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, publicKey, false, TOKEN_PROGRAM_ID);
      const tradingUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, TRADING_WALLET, false, TOKEN_PROGRAM_ID);

      const transaction = new Transaction();

      // Check if user USDC account exists, create if not
      const userUsdcAccountInfo = await connection.getAccountInfo(userUsdcAta);
      if (!userUsdcAccountInfo) {
        transaction.add(
          createAssociatedTokenAccountInstruction(
            publicKey, userUsdcAta, publicKey, USDC_MINT
          )
        );
      }

      // Check if user already has a UserShare (for registry logic)
      const existingUserShare = await connection.getAccountInfo(userSharePda);
      
      // Build stake instruction based on StakeUsdc context from the program
      const discriminator = Buffer.from(DISCRIMINATORS.stake_usdc);
      const amountBuffer = Buffer.alloc(8);
      amountBuffer.writeBigUInt64LE(BigInt(amountRaw), 0);
      const instructionData = Buffer.concat([discriminator, amountBuffer]);

      const accounts = [
        { pubkey: publicKey, isSigner: true, isWritable: true }, // user
        { pubkey: userUsdcAta, isSigner: false, isWritable: true }, // user_usdc_account
        { pubkey: userSharePda, isSigner: false, isWritable: true }, // user_share
        { pubkey: fundPoolPda, isSigner: false, isWritable: true }, // fund_pool
        { pubkey: TRADING_WALLET, isSigner: false, isWritable: false }, // trading_wallet
        { pubkey: tradingUsdcAta, isSigner: false, isWritable: true }, // trading_usdc_account
        { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false }, // token_program
        { pubkey: SystemProgram.programId, isSigner: false, isWritable: false }, // system_program
      ];

      // Always add registry accounts (the program expects them)
      accounts.push({ pubkey: REGISTRY_DIRECTORY_PDA, isSigner: false, isWritable: true }); // registry_directory
      
      // For new users, use registry 0; for existing users, get their registry from UserShare
      let userRegistryPda;
      if (existingUserShare) {
        // Read registry ID from existing UserShare
        const registryId = Number(existingUserShare.data.readBigUInt64LE(56));
        const registryIdBuffer = Buffer.alloc(8);
        registryIdBuffer.writeBigUInt64LE(BigInt(registryId), 0);
        [userRegistryPda] = PublicKey.findProgramAddressSync(
          [Buffer.from("user_registry_v2"), registryIdBuffer], 
          PROGRAM_ID
        );
      } else {
        // For new users, use registry 0 (should be more sophisticated registry selection)
        const registryIdBuffer = Buffer.alloc(8);
        registryIdBuffer.writeBigUInt64LE(BigInt(0), 0);
        [userRegistryPda] = PublicKey.findProgramAddressSync(
          [Buffer.from("user_registry_v2"), registryIdBuffer], 
          PROGRAM_ID
        );
      }
      accounts.push({ pubkey: userRegistryPda, isSigner: false, isWritable: true }); // user_registry

      const stakeInstruction = new TransactionInstruction({
        keys: accounts,
        programId: PROGRAM_ID,
        data: instructionData,
      });

      transaction.add(stakeInstruction);

      // Simulate the transaction first to see the actual error
      try {
        transaction.feePayer = publicKey;
        transaction.recentBlockhash = (await connection.getLatestBlockhash()).blockhash;
        
        const simulation = await connection.simulateTransaction(transaction);
        
        if (simulation.value.err) {
          throw new Error(`Simulation failed: ${JSON.stringify(simulation.value.err)}`);
        }
      } catch (simError: any) {
        throw new Error(`Simulation error: ${simError.message}`);
      }

      const signature = await sendTransaction(transaction, connection);
      await connection.confirmTransaction(signature, 'confirmed');

      setFundAmount('');
      toast.success('Stake successful! Signature: ' + signature);

      // Refresh data
      await refreshUserData();

    } catch (error: any) {
      console.error('Staking failed:', error);
      toast.error(error.message || 'Staking failed');
    } finally {
      setIsStaking(false);
    }
  };

  return (
    <>
      <h2>Stake USDC in Shrub Fund</h2>
      
      {publicKey && (
        <div className="balance-card">
          <div className="balance-row">
            <span>Your USDC Balance:</span>
            <span className="balance-value">{loadingUserData ? 'Loading...' : balances.usdc.toFixed(2)}</span>
          </div>
          <div className="balance-row">
            <span>Your Fund Shares:</span>
            <span className="balance-value-green">{loadingUserData ? 'Loading...' : userInfo.shares.toFixed(2)}</span>
          </div>
          <div className="balance-row">
            <span>Share Value:</span>
            <span className="balance-value-green">{loadingUserData ? 'Loading...' : `$${userInfo.shareValue.toFixed(2)}`}</span>
          </div>
        </div>
      )}

      <div className="form-section">
        <div className="input-group">
          <label className="input-label">Amount (USDC)</label>
          <div className="input-container">
            <input
              type="number"
              value={fundAmount}
              onChange={(e) => setFundAmount(e.target.value)}
              placeholder="0.00"
              className="amount-input"
              disabled={!publicKey || isStaking}
            />
            <div className="input-suffix">USDC</div>
          </div>
          {fundAmount && (
            <p className="conversion-text">
              You will receive ~{(parseFloat(fundAmount || '0') / stats.realNav).toFixed(2)} shares
            </p>
          )}
          <p style={styling.createStyle({
            fontSize: '$fontSize.xs',
            color: '$colors.text.gray',
            fontStyle: 'italic',
            marginTop: '$spacing.sm',
            textAlign: 'center'
          })}>
            ⏰ NAV updates automatically every 2 hours after staking
          </p>
        </div>

        <button
          onClick={handleStakeFund}
          disabled={!isValidFundAmount || isStaking}
          className="contribute-button"
        >
          {isStaking ? (
            <div className="spinner" />
          ) : !publicKey ? (
            <>
              <span>Connect Wallet</span>
              <span style={styling.createStyle({ fontSize: '$fontSize.md' })}>{ARROW_RIGHT_ICON}</span>
            </>
          ) : (
            <>
              <span style={styling.createStyle({ fontSize: '$fontSize.md' })}>{LOCK_ICON}</span>
              <span>Stake USDC</span>
            </>
          )}
        </button>
      </div>
    </>
  );
};

export default FundTab;