// src/hooks/useUserData.ts (hook for user data)
import { useState, useEffect } from 'react';
import { PublicKey, Connection } from '@solana/web3.js';
import { getAssociatedTokenAddressSync } from '@solana/spl-token';
import { toast } from 'react-toastify';
import { PROGRAM_ID, USDC_MINT, REGISTRY_DIRECTORY_PDA, TOKEN_PROGRAM_ID, PENDING_CASHOUT_POOL_PDA } from '../utils/constants';
import { canUnstake } from '../utils/shrub-fund-client';

interface UserInfo {
  shares: number;
  shareValue: number;
  canUnstake: boolean;
  stakeTimestamp: number;
  hasPendingUnstake: boolean;
  pendingUnstakeValue: number;
  unstakeInitiatedTimestamp: number;
  canCompleteUnstake: boolean;
  unstakeCompleteTime: number;
}

interface RegistrySlot {
  registryId: number;
  needsCreation: boolean;
}

const useUserData = (publicKey: PublicKey | null, connection: Connection | null, activeTab: string, realNav: number = 1.0) => {
  const [userInfo, setUserInfo] = useState<UserInfo>({
    shares: 0,
    shareValue: 0,
    canUnstake: false,
    stakeTimestamp: 0,
    hasPendingUnstake: false,
    pendingUnstakeValue: 0,
    unstakeInitiatedTimestamp: 0,
    canCompleteUnstake: false,
    unstakeCompleteTime: 0
  });
  const [balances, setBalances] = useState({ usdc: 0 });
  const [loadingUserData, setLoadingUserData] = useState(false);
  const [cachedRegistrySlot, setCachedRegistrySlot] = useState<RegistrySlot | null>(null);
  const [preloadingRegistry, setPreloadingRegistry] = useState(false);

  const fetchUnstakeTimestampFromRegistry = async () => {
    if (!publicKey || !connection) return null;
    
    try {
      console.log('🔍 DEBUGGING fetchUnstakeTimestampFromRegistry');
      
      // Get UserShare to find registry info
      const [userSharePda] = PublicKey.findProgramAddressSync(
        [Buffer.from("user_share_v2"), publicKey.toBuffer()], 
        PROGRAM_ID
      );
      
      const userShareData = await connection.getAccountInfo(userSharePda);
      if (!userShareData) {
        console.log('❌ No UserShare data found');
        return null;
      }
      
      const registryId = Number(userShareData.data.readBigUInt64LE(56));
      const registryIndex = Number(userShareData.data.readBigUInt64LE(64));
      
      console.log('📊 UserShare info:', { registryId, registryIndex });
      
      // Derive UserRegistry PDA
      const registryIdBuffer = Buffer.alloc(8);
      registryIdBuffer.writeBigUInt64LE(BigInt(registryId), 0);
      const [userRegistryPda] = PublicKey.findProgramAddressSync(
        [Buffer.from("user_registry_v2"), registryIdBuffer], 
        PROGRAM_ID
      );
      
      console.log('🏗️ UserRegistry PDA:', userRegistryPda.toString());
      
      const userRegistryData = await connection.getAccountInfo(userRegistryPda);
      if (!userRegistryData) {
        console.log('❌ No UserRegistry data found');
        return null;
      }
      
      console.log('📏 UserRegistry data length:', userRegistryData.data.length);
      console.log('🔍 Raw UserRegistry data (first 100 bytes):', 
        Array.from(userRegistryData.data.slice(0, 100))
          .map(b => b.toString(16).padStart(2, '0')).join(' '));
      
      // Let's try a simpler approach - search for the user's pubkey in the registry
      const userPubkeyBytes = publicKey.toBuffer();
      let foundOffset = -1;
      
      // Search for the user's pubkey in the registry data
      for (let i = 0; i <= userRegistryData.data.length - 32; i++) {
        if (userRegistryData.data.slice(i, i + 32).equals(userPubkeyBytes)) {
          foundOffset = i;
          console.log('✅ Found user pubkey at offset:', i);
          break;
        }
      }
      
      if (foundOffset === -1) {
        console.log('❌ User pubkey not found in registry');
        return null;
      }
      
      // The unstake_initialized_timestamp should be after: pubkey(32) + shares(8) + stake_timestamp(8)
      // So look for the Option<i64> at foundOffset + 48
      const timestampOffset = foundOffset + 32 + 8 + 8;
      
      if (timestampOffset + 9 <= userRegistryData.data.length) {
        // Check if it's Some(timestamp)
        if (userRegistryData.data.readUInt8(timestampOffset) === 1) {
          const unstakeInitiatedTimestamp = Number(userRegistryData.data.readBigInt64LE(timestampOffset + 1));
          console.log('✅ Found unstake timestamp:', unstakeInitiatedTimestamp);
          console.log('📅 Timestamp as date:', new Date(unstakeInitiatedTimestamp * 1000).toISOString());
          return unstakeInitiatedTimestamp;
        } else {
          console.log('❌ Unstake timestamp is None');
        }
      }
      
      return null;
    } catch (error) {
      console.error('Error fetching unstake timestamp from registry:', error);
      return null;
    }
  };

  const fetchPendingUnstakeFromPool = async () => {
    if (!publicKey || !connection) return null;
    try {
      console.log('🔍 DEBUGGING fetchPendingUnstakeFromPool');
      
      // Get pending cashout pool data  
      const pendingCashoutPoolData = await connection.getAccountInfo(PENDING_CASHOUT_POOL_PDA);
      if (!pendingCashoutPoolData) {
        console.log('❌ Pending cashout pool not found');
        return null;
      }
      
      console.log('📏 Pending cashout pool data length:', pendingCashoutPoolData.data.length);
      
      // Parse PendingCashoutPool structure: discriminator(8) + users_vec_len(4) + users...
      const usersVecLen = pendingCashoutPoolData.data.readUInt32LE(8);
      console.log('👥 Users in pending pool:', usersVecLen);
      
      if (usersVecLen === 0) {
        console.log('❌ No users in pending pool');
        return null;
      }
      
      // Each PendingUsers entry: user(32) + pending_usdc_cashout(8) = 40 bytes
      let userOffset = 12; // After discriminator(8) + vec_len(4)
      
      for (let i = 0; i < usersVecLen; i++) {
        if (userOffset + 40 > pendingCashoutPoolData.data.length) {
          console.log('❌ Offset out of bounds at index', i);
          break;
        }
        
        const userPubkeyFromPool = new PublicKey(pendingCashoutPoolData.data.slice(userOffset, userOffset + 32));
        const pendingUsdcCashout = Number(pendingCashoutPoolData.data.readBigUInt64LE(userOffset + 32));
        
        console.log(`👤 Pool user ${i}:`, userPubkeyFromPool.toString(), 'Amount:', pendingUsdcCashout);
        
        if (userPubkeyFromPool.equals(publicKey)) {
          const lockedValue = pendingUsdcCashout / 1_000_000;
          console.log('✅ Found user in pending pool! Locked value:', lockedValue);
          
          // We don't have initiation timestamp from pool, so we'll estimate from UserRegistry or use current time
          // For now, let's just return a reasonable timestamp (this could be improved)
          const estimatedTimestamp = Math.floor(Date.now() / 1000) - (24 * 60 * 60); // Assume 1 day ago for now
          
          return { lockedValue, initiationTimestamp: estimatedTimestamp };
        }
        
        userOffset += 40;
      }
      
      console.log('❌ User not found in pending pool');
      return null;
    } catch (error) {
      console.error('Error fetching pending unstake from pool:', error);
      return null;
    }
  };

  const fetchUserShareInfo = async (): Promise<UserInfo | null> => {
    if (!publicKey || !connection) return null;
    try {
      const [userSharePda] = PublicKey.findProgramAddressSync(
        [Buffer.from("user_share_v2"), publicKey.toBuffer()], 
        PROGRAM_ID
      );
      
      const userShareData = await connection.getAccountInfo(userSharePda);
      if (!userShareData) return null;
      
      // Parse UserShare: discriminator(8) + user(32) + shares(8) + stake_timestamp(8) + registry_id(8) + registry_index(8) + unstake_initiated(1)
      const shares = Number(userShareData.data.readBigUInt64LE(40)) / 1_000_000; // USDC decimals
      const stakeTimestamp = Number(userShareData.data.readBigInt64LE(48));
      const unstakeInitiated = userShareData.data.length > 72 ? userShareData.data.readUInt8(72) !== 0 : false;
      
      // If unstake initiated, try to fetch pending unstake info and timing
      const pendingUnstake = unstakeInitiated ? await fetchPendingUnstakeFromPool() : null;
      const unstakeInitiatedTimestamp = unstakeInitiated ? await fetchUnstakeTimestampFromRegistry() : 0;
      
      // Calculate when unstake can be completed (7 days after initiation)
      const sevenDaysInSeconds = 7 * 24 * 60 * 60;
      const unstakeCompleteTime = unstakeInitiatedTimestamp ? unstakeInitiatedTimestamp + sevenDaysInSeconds : 0;
      const now = Math.floor(Date.now() / 1000);
      const canCompleteUnstake = unstakeInitiated && unstakeCompleteTime > 0 && now >= unstakeCompleteTime;
      
      // For users with pending unstake, use the locked value instead of current NAV
      const shareValue = unstakeInitiated && pendingUnstake?.lockedValue 
        ? pendingUnstake.lockedValue 
        : shares * realNav;
      
      return {
        shares,
        shareValue,
        canUnstake: canUnstake(stakeTimestamp),
        stakeTimestamp,
        hasPendingUnstake: unstakeInitiated,
        pendingUnstakeValue: pendingUnstake?.lockedValue || 0,
        unstakeInitiatedTimestamp: unstakeInitiatedTimestamp || 0,
        canCompleteUnstake,
        unstakeCompleteTime
      };
    } catch (error) {
      console.error('Error fetching user share info:', error);
      return null;
    }
  };

  const prefindAvailableRegistrySlot = async () => {
    if (!publicKey || !connection) return;

    setPreloadingRegistry(true);

    try {
      const registryDirectory = await connection.getAccountInfo(REGISTRY_DIRECTORY_PDA);
      if (!registryDirectory) throw new Error('Registry directory not found');

      const data = registryDirectory.data.slice(8);
      const registryCount = Number(data.readBigUInt64LE(0));

      let needsCreation = true;
      let registryId = registryCount;

      // For new users, registryId is the next slot

      setCachedRegistrySlot({ registryId, needsCreation });
      console.log(`Preloaded registry slot: ${registryId}, needs creation: ${needsCreation}`);
    } catch (error) {
      console.error('Error prefinding registry slot:', error);
      setCachedRegistrySlot(null);
    } finally {
      setPreloadingRegistry(false);
    }
  };

  const refreshUserData = async () => {
    if (!publicKey || !connection) {
      setUserInfo({
        shares: 0,
        shareValue: 0,
        canUnstake: false,
        stakeTimestamp: 0,
        hasPendingUnstake: false,
        pendingUnstakeValue: 0,
        unstakeInitiatedTimestamp: 0,
        canCompleteUnstake: false,
        unstakeCompleteTime: 0
      });
      setBalances({ usdc: 0 });
      return;
    }

    setLoadingUserData(true);

    try {
      // Fetch user shares
      const shareInfo = await fetchUserShareInfo();
      if (shareInfo) {
        setUserInfo(shareInfo);
      } else {
        setUserInfo({
          shares: 0,
          shareValue: 0,
          canUnstake: false,
          stakeTimestamp: 0,
          hasPendingUnstake: false,
          pendingUnstakeValue: 0,
          unstakeInitiatedTimestamp: 0,
          canCompleteUnstake: false,
          unstakeCompleteTime: 0
        });
      }

      // Fetch USDC balance
      const usdcAta = getAssociatedTokenAddressSync(USDC_MINT, publicKey, false, TOKEN_PROGRAM_ID);
      const balanceInfo = await connection.getTokenAccountBalance(usdcAta).catch(() => null);
      const usdcBalance = balanceInfo ? balanceInfo.value.uiAmount || 0 : 0;
      setBalances({ usdc: usdcBalance });
    } catch (error) {
      console.error('Error fetching user data:', error);
      toast.error('Failed to fetch user data');
    } finally {
      setLoadingUserData(false);
    }
  };

  // Fetch user info and balances when wallet connects or tab changes
  useEffect(() => {
    refreshUserData();
  }, [publicKey, connection, activeTab, realNav]); // Add realNav to refresh share value when NAV updates

  // Registry preloading effect - triggers when wallet connects
  useEffect(() => {
    if (publicKey && connection) {
      // Check if user is existing or new, then preload if new
      fetchUserShareInfo().then(userShare => {
        if (!userShare) {
          // New user - start preloading available registry slot
          console.log('New user detected, preloading registry slot...');
          prefindAvailableRegistrySlot();
        } else {
          console.log('Existing user, no registry preloading needed');
        }
      }).catch(error => {
        console.warn('Error checking user status for preloading:', error);
      });
    } else {
      // Wallet disconnected - clear cached slot
      setCachedRegistrySlot(null);
    }
  }, [publicKey, connection]);

  return { userInfo, balances, loadingUserData, refreshUserData, cachedRegistrySlot, preloadingRegistry };
};

export default useUserData;