// src/utils/shrub-fund-client.ts (extracted helper functions)
import { PublicKey, Connection, TransactionInstruction, SystemProgram, Transaction } from '@solana/web3.js';
import { TOKEN_PROGRAM_ID, getAssociatedTokenAddressSync, createAssociatedTokenAccountInstruction } from '@solana/spl-token';
import { PROGRAM_ID, USDC_MINT, FUND_POOL_PDA, NAV_HISTORY_PDA, PENDING_CASHOUT_POOL_PDA, REGISTRY_DIRECTORY_PDA, DISCRIMINATORS, TRADING_WALLET } from './constants';
import { toast } from 'react-toastify';

// Helper to check if unstake is possible
export const canUnstake = (stakeTimestamp: number) => {
  const now = Date.now() / 1000;
  return now >= stakeTimestamp + 7 * 24 * 60 * 60; // 7 days in seconds
};

// Get PDA for user registry
export const getUserRegistryPda = (user: PublicKey) => {
  return PublicKey.findProgramAddressSync(
    [Buffer.from("user_registry"), user.toBuffer()],
    PROGRAM_ID
  )[0];
};

// Get PDA for registry by ID
export const getRegistryPda = (registryId: number) => {
  return PublicKey.findProgramAddressSync(
    [Buffer.from("registry"), new Uint8Array([registryId])],
    PROGRAM_ID
  )[0];
};

// Fetch user registry account info
export const fetchUserRegistry = async (user: PublicKey, connection: Connection) => {
  const userRegistryPda = getUserRegistryPda(user);
  return await connection.getAccountInfo(userRegistryPda);
};

// Parse user registry data
export const parseUserRegistry = (accountData: Buffer | null) => {
  if (!accountData) return null;

  const data = accountData.slice(8); // Skip discriminator
  return {
    shares: Number(data.readBigUInt64LE(0)),
    stakeTimestamp: Number(data.readBigUInt64LE(8)),
    hasPendingUnstake: !!data[16],
    unstakeTimestamp: Number(data.readBigUInt64LE(17)), // Assuming offset
  };
};

// Fetch user share info (simple check if exists)
export const fetchUserShareInfo = async (user: PublicKey, connection: Connection) => {
  try {
    const registryAccount = await fetchUserRegistry(user, connection);
    if (!registryAccount) return null;

    const data = registryAccount.data.slice(8);
    const shares = Number(data.readBigUInt64LE(0));
    return { shares };
  } catch (error) {
    return null;
  }
};

// Prefind available registry slot
export const prefindAvailableRegistrySlot = async (connection: Connection) => {
  try {
    const directory = await connection.getAccountInfo(REGISTRY_DIRECTORY_PDA);
    if (!directory) throw new Error('Registry directory not found');

    const data = directory.data.slice(8);
    const totalRegistries = Number(data.readBigUInt64LE(0));

    for (let registryId = 0; registryId < totalRegistries; registryId++) {
      const registryPda = getRegistryPda(registryId);
      const registryAccount = await connection.getAccountInfo(registryPda);
      if (!registryAccount) continue;

      const registryData = registryAccount.data.slice(8);
      const totalUsers = Number(registryData.readBigUInt64LE(0));
      if (totalUsers < 100) { // Assuming 100 slots per registry
        return { registryId, needsCreation: false };
      }
    }

    // All full, need new registry
    return { registryId: totalRegistries, needsCreation: true };
  } catch (error) {
    console.error('Registry preload failed:', error);
    toast.error('Failed to preload registry slot');
    return null;
  }
};

// Build create registry instruction (if needed)
export const buildCreateRegistryInstruction = (payer: PublicKey, registryId: number) => {
  const data = Buffer.alloc(1);
  data.writeUInt8(registryId, 0);

  const newRegistryPda = getRegistryPda(registryId);

  // Assuming discriminator for create_registry, using a placeholder if not defined
  const createDiscriminator = [0, 0, 0, 0, 0, 0, 0, 0]; // Replace with actual if known

  return new TransactionInstruction({
    keys: [
      { pubkey: payer, isSigner: true, isWritable: true },
      { pubkey: REGISTRY_DIRECTORY_PDA, isSigner: false, isWritable: true },
      { pubkey: newRegistryPda, isSigner: false, isWritable: true },
      { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
    ],
    programId: PROGRAM_ID,
    data: Buffer.concat([Buffer.from(createDiscriminator), data]),
  });
};

// Build stake instruction
export const buildStakeInstruction = (user: PublicKey, amount: number, registryId: number) => {
  const data = Buffer.alloc(1 + 8);
  data.writeUInt8(registryId, 0);
  data.writeBigUInt64LE(BigInt(amount), 1);

  const userRegistryPda = getUserRegistryPda(user);
  const registryPda = getRegistryPda(registryId);

  return new TransactionInstruction({
    keys: [
      { pubkey: user, isSigner: true, isWritable: true },
      { pubkey: userRegistryPda, isSigner: false, isWritable: true },
      { pubkey: registryPda, isSigner: false, isWritable: true },
      { pubkey: REGISTRY_DIRECTORY_PDA, isSigner: false, isWritable: true },
      { pubkey: FUND_POOL_PDA, isSigner: false, isWritable: true },
      { pubkey: getAssociatedTokenAddressSync(USDC_MINT, user), isSigner: false, isWritable: true },
      { pubkey: getAssociatedTokenAddressSync(USDC_MINT, FUND_POOL_PDA, true), isSigner: false, isWritable: true },
      { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
      { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
    ],
    programId: PROGRAM_ID,
    data: Buffer.concat([Buffer.from(DISCRIMINATORS.stake_usdc), data]),
  });
};

// Helper to ensure fund ATA exists
export const ensureFundAta = async (connection: Connection, payer: PublicKey, transaction: Transaction) => {
  const fundUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, FUND_POOL_PDA, true, TOKEN_PROGRAM_ID);
  const fundAtaInfo = await connection.getAccountInfo(fundUsdcAta);

  if (!fundAtaInfo) {
    transaction.add(
      createAssociatedTokenAccountInstruction(
        payer,
        fundUsdcAta,
        FUND_POOL_PDA,
        USDC_MINT,
        TOKEN_PROGRAM_ID
      )
    );
  }
};

// Build initiate unstake instruction
export const buildInitiateUnstakeInstruction = (user: PublicKey) => {
  const data = Buffer.alloc(0); // No additional data

  const userRegistryPda = getUserRegistryPda(user);

  return new TransactionInstruction({
    keys: [
      { pubkey: user, isSigner: true, isWritable: true },
      { pubkey: userRegistryPda, isSigner: false, isWritable: true },
      { pubkey: FUND_POOL_PDA, isSigner: false, isWritable: true },
      { pubkey: NAV_HISTORY_PDA, isSigner: false, isWritable: true },
      { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
    ],
    programId: PROGRAM_ID,
    data: Buffer.concat([Buffer.from(DISCRIMINATORS.initiate_unstake), data]),
  });
};

// Build complete unstake instruction
export const buildCompleteUnstakeInstruction = (user: PublicKey) => {
  const data = Buffer.alloc(0); // No additional data

  const userRegistryPda = getUserRegistryPda(user);
  const pendingCashoutUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, PENDING_CASHOUT_POOL_PDA, true, TOKEN_PROGRAM_ID);
  const userUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, user, false, TOKEN_PROGRAM_ID);

  return new TransactionInstruction({
    keys: [
      { pubkey: user, isSigner: true, isWritable: true },
      { pubkey: userRegistryPda, isSigner: false, isWritable: true },
      { pubkey: FUND_POOL_PDA, isSigner: false, isWritable: true },
      { pubkey: PENDING_CASHOUT_POOL_PDA, isSigner: false, isWritable: true },
      { pubkey: pendingCashoutUsdcAta, isSigner: false, isWritable: true },
      { pubkey: userUsdcAta, isSigner: false, isWritable: true },
      { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
      { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
    ],
    programId: PROGRAM_ID,
    data: Buffer.concat([Buffer.from(DISCRIMINATORS.complete_unstake), data]),
  });
};

// Build update fund NAV instruction (for gardener)
export const buildUpdateFundNavInstruction = (gardener: PublicKey, newNav: number) => {
  const data = Buffer.alloc(8);
  data.writeBigUInt64LE(BigInt(Math.floor(newNav * 1_000_000)), 0); // Convert to units

  return new TransactionInstruction({
    keys: [
      { pubkey: gardener, isSigner: true, isWritable: false },
      { pubkey: FUND_POOL_PDA, isSigner: false, isWritable: true },
      { pubkey: NAV_HISTORY_PDA, isSigner: false, isWritable: true },
      { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
    ],
    programId: PROGRAM_ID,
    data: Buffer.concat([Buffer.from(DISCRIMINATORS.update_optimized_nav), data]),
  });
};

// Fetch USDC balance
export const fetchUsdcBalance = async (user: PublicKey, connection: Connection) => {
  const usdcAta = getAssociatedTokenAddressSync(USDC_MINT, user, false, TOKEN_PROGRAM_ID);
  const balance = await connection.getTokenAccountBalance(usdcAta).catch(() => ({ value: { uiAmount: 0 } }));
  return balance.value.uiAmount || 0;
};

// Fetch pending cashout value
export const fetchPendingCashout = async (connection: Connection) => {
  const fundPoolInfo = await connection.getAccountInfo(FUND_POOL_PDA);
  if (!fundPoolInfo) return 0;

  const data = fundPoolInfo.data.slice(8);
  const pendingCashout = Number(data.readBigUInt64LE(40));
  return pendingCashout / 1_000_000; // Convert to USDC
};

// Fetch PDA SOL balances for gardener
export const fetchPdaSolBalances = async (connection: Connection) => {
  const fundPoolSol = await connection.getBalance(FUND_POOL_PDA) / 1_000_000_000;
  const navHistorySol = await connection.getBalance(NAV_HISTORY_PDA) / 1_000_000_000;
  const pendingCashoutPoolSol = await connection.getBalance(PENDING_CASHOUT_POOL_PDA) / 1_000_000_000;
  const registryDirectorySol = await connection.getBalance(REGISTRY_DIRECTORY_PDA) / 1_000_000_000;

  return {
    fundPool: fundPoolSol,
    navHistory: navHistorySol,
    pendingCashoutPool: pendingCashoutPoolSol,
    registryDirectory: registryDirectorySol,
  };
};

// Fetch trading wallet USDC balance
export const fetchTradingWalletBalance = async (connection: Connection) => {
  const tradingUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, TRADING_WALLET, false, TOKEN_PROGRAM_ID);
  const balance = await connection.getTokenAccountBalance(tradingUsdcAta).catch(() => ({ value: { uiAmount: 0 } }));
  return balance.value.uiAmount || 0;
};

// Fetch registry health (total users, registries)
export const fetchRegistryHealth = async (connection: Connection) => {
  const directory = await connection.getAccountInfo(REGISTRY_DIRECTORY_PDA);
  if (!directory) return { totalUsers: 0, totalRegistries: 0 };

  const data = directory.data.slice(8);
  const totalRegistries = Number(data.readBigUInt64LE(0));
  let totalUsers = 0;

  for (let id = 0; id < totalRegistries; id++) {
    const registryPda = getRegistryPda(id);
    const regAccount = await connection.getAccountInfo(registryPda);
    if (regAccount) {
      const regData = regAccount.data.slice(8);
      totalUsers += Number(regData.readBigUInt64LE(0));
    }
  }

  return { totalUsers, totalRegistries };
};

// Fetch pending cashout pool USDC balance
export const fetchPendingCashoutPoolBalance = async (connection: Connection) => {
  const pendingUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, PENDING_CASHOUT_POOL_PDA, true, TOKEN_PROGRAM_ID);
  const balance = await connection.getTokenAccountBalance(pendingUsdcAta).catch(() => ({ value: { uiAmount: 0 } }));
  return balance.value.uiAmount || 0;
};