import React, { useState, useEffect } from 'react';
import { PublicKey, Connection } from '@solana/web3.js';
import { Link } from 'react-router-dom';
import FundTab from './FundTab';
import UnstakeTab from './UnstakeTab';
import { useStyling } from '../hooks/useStyling';

interface ShrubStakesTabProps {
  publicKey: PublicKey | null;
  connection: Connection;
  sendTransaction: any;
  stats: { totalFundValue: number; totalShares: number; nav: number; realNav: number };
  userInfo: {
    shares: number;
    shareValue: number;
    canUnstake: boolean;
    stakeTimestamp: number;
    hasPendingUnstake: boolean;
    pendingUnstakeValue: number;
    unstakeInitiatedTimestamp: number;
    canCompleteUnstake: boolean;
    unstakeCompleteTime: number;
  };
  balances: { usdc: number };
  loadingStats: boolean;
  loadingUserData: boolean;
  refreshUserData: () => Promise<void>;
}

const ShrubStakesTab: React.FC<ShrubStakesTabProps> = ({
  publicKey,
  connection,
  sendTransaction,
  stats,
  userInfo,
  balances,
  loadingStats,
  loadingUserData,
  refreshUserData,
}) => {
  const styling = useStyling();
  const [activeSubTab, setActiveSubTab] = useState('stake');
  const [showOnboardingSection, setShowOnboardingSection] = useState(true);

  // Check localStorage on component mount
  useEffect(() => {
    const dismissed = localStorage.getItem('shrub-onboarding-dismissed');
    if (dismissed === 'true') {
      setShowOnboardingSection(false);
    }
  }, []);

  // Function to dismiss the onboarding section
  const dismissOnboardingSection = () => {
    setShowOnboardingSection(false);
    localStorage.setItem('shrub-onboarding-dismissed', 'true');
  };

  const subTabContainerStyle = styling.createStyle({
    display: 'flex',
    gap: '$spacing.sm',
    marginBottom: '$spacing.xl',
    justifyContent: 'center',
  });

  const subTabButtonStyle = (isActive: boolean) => styling.createStyle({
    padding: `${styling.getSpacing('sm')} ${styling.getSpacing('lg')}`,
    background: isActive ? '$colors.primary.gradient' : '$colors.background.dark',
    border: `1px solid ${styling.getColor('border.gray')}`,
    borderRadius: '$borderRadius.md',
    color: '$colors.text.white',
    fontWeight: '$fontWeight.semibold',
    cursor: 'pointer',
    transition: '$transitions.default',
    fontSize: '$fontSize.sm',
  });

  return (
    <div>
      {/* Onboarding Guide Link - Dismissible */}
      {showOnboardingSection && (
        <div style={{
          background: 'rgba(16, 185, 129, 0.1)',
          border: '1px solid rgba(16, 185, 129, 0.3)',
          borderRadius: '12px',
          padding: '16px',
          marginBottom: '24px',
          textAlign: 'center',
          position: 'relative'
        }}>
          {/* Close Button */}
          <button
            onClick={dismissOnboardingSection}
            style={{
              position: 'absolute',
              top: '8px',
              right: '8px',
              background: 'none',
              border: 'none',
              color: '#9ca3af',
              fontSize: '16px',
              cursor: 'pointer',
              padding: '4px',
              borderRadius: '4px',
              transition: 'all 0.2s ease',
              width: '24px',
              height: '24px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.background = 'rgba(239, 68, 68, 0.1)';
              e.currentTarget.style.color = '#ef4444';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.background = 'none';
              e.currentTarget.style.color = '#9ca3af';
            }}
            title="Dismiss this message"
          >
            ✕
          </button>

          <p style={{
            color: '#9ca3af',
            margin: '0 0 12px 0',
            fontSize: '14px'
          }}>
            Don't know what to do? Visit the Onboarding Guide
          </p>
          <Link
            to="/onboarding"
            style={{
              background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)',
              color: 'white',
              padding: '8px 16px',
              borderRadius: '8px',
              textDecoration: 'none',
              fontSize: '14px',
              fontWeight: '600',
              display: 'inline-block',
              transition: 'all 0.2s ease'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translateY(-1px)';
              e.currentTarget.style.boxShadow = '0 4px 12px rgba(16, 185, 129, 0.4)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translateY(0)';
              e.currentTarget.style.boxShadow = 'none';
            }}
          >
            📚 View Onboarding Guide
          </Link>
        </div>
      )}

      <div style={subTabContainerStyle}>
        <button
          style={subTabButtonStyle(activeSubTab === 'stake')}
          onClick={() => setActiveSubTab('stake')}
        >
          Stake
        </button>
        <button
          style={subTabButtonStyle(activeSubTab === 'unstake')}
          onClick={() => setActiveSubTab('unstake')}
        >
          Unstake
        </button>
      </div>

      {activeSubTab === 'stake' && (
        <FundTab
          publicKey={publicKey}
          connection={connection}
          sendTransaction={sendTransaction}
          stats={stats}
          userInfo={userInfo}
          balances={balances}
          loadingStats={loadingStats}
          loadingUserData={loadingUserData}
          refreshUserData={refreshUserData}
        />
      )}

      {activeSubTab === 'unstake' && (
        <UnstakeTab
          publicKey={publicKey}
          connection={connection}
          sendTransaction={sendTransaction}
          userInfo={userInfo}
          canUnstake={userInfo.canUnstake}
          refreshUserData={refreshUserData}
        />
      )}
    </div>
  );
};

export default ShrubStakesTab;