// src/components/Tabs.tsx (extracted tab navigation JSX)
import React from 'react';
import { PublicKey } from '@solana/web3.js';
import { GARDENER_WALLET } from '../utils/constants';
import { useStyling } from '../hooks/useStyling';

interface TabsProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  publicKey: PublicKey | null;
}

const Tabs: React.FC<TabsProps> = ({ activeTab, setActiveTab, publicKey }) => {
  const styling = useStyling();
  const isGardener = publicKey && publicKey.toString() === GARDENER_WALLET.toString();

  const containerStyle = styling.createStyle({
    marginBottom: '$spacing.xxl'
  });

  const tabContainerStyle = styling.createStyle({
    display: 'flex',
    background: '$colors.background.dark',
    borderRadius: '$borderRadius.lg',
    padding: '$spacing.xs',
    border: `1px solid ${styling.getColor('border.gray')}`
  });

  const getButtonStyle = (isActive: boolean) => styling.createStyle({
    flex: 1,
    padding: `${styling.getSpacing('md')} ${styling.getSpacing('lg')}`,
    background: isActive ? '$colors.primary.gradient' : '$colors.background.transparent',
    border: 'none',
    borderRadius: '$borderRadius.md',
    color: '$colors.text.white',
    fontWeight: '$fontWeight.semibold',
    cursor: 'pointer',
    transition: '$transitions.default',
    fontSize: '$fontSize.sm'
  });

  return (
    <div style={containerStyle}>
      <div style={tabContainerStyle}>
        {[
          { key: 'shrub-stakes', label: 'Invest' },
          { key: 'shrub-send', label: 'Safe Send' },
          { key: 'shrub-swaps', label: 'Token Swap' }
        ].map((tab) => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            style={getButtonStyle(activeTab === tab.key)}
          >
            {tab.label}
          </button>
        ))}
      </div>
    </div>
  );
};

export default Tabs;