// src/components/Header.tsx
import React, { useState, useEffect } from 'react';
import { WalletMultiButton } from '@solana/wallet-adapter-react-ui';
import logo40 from '../logo-40.png';
import navigationConfig from './navigation.json';
import { Link } from 'react-router-dom';

interface LinkItem {
  text: string;
  url: string;
}

interface SubmenuItem {
  text: string;
  content: { [key: string]: LinkItem };
}

interface NavigationData {
  header: {
    links: { [key: string]: LinkItem };
    [key: string]: any;
  };
}

const Header = () => {
  const renderLink = (url: string, text: string, className: string, onClick?: () => void) => {
    if (url.startsWith('/')) {
      return <Link to={url} className={className} onClick={onClick}>{text}</Link>;
    } else {
      return <a href={url} className={className} onClick={onClick}>{text}</a>;
    }
  };

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [openSubmenu, setOpenSubmenu] = useState<string | null>(null);
  const [isMobile, setIsMobile] = useState(false);

  const navigation = navigationConfig as NavigationData;

  useEffect(() => {
    const checkMobile = () => {
      const mobile = window.innerWidth <= 1024;
      setIsMobile(mobile);
      if (!mobile) {
        setIsMobileMenuOpen(false);
        setOpenSubmenu(null);
      }
    };

    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
    setOpenSubmenu(null);
  };

  const toggleSubmenu = (submenuKey: string) => {
    setOpenSubmenu(openSubmenu === submenuKey ? null : submenuKey);
  };

  const handleLinkClick = () => {
    if (isMobile) {
      setIsMobileMenuOpen(false);
      setOpenSubmenu(null);
    }
  };

  const renderDesktopLinks = () => {
    const headerData = navigation.header;
    const links = headerData.links || {};
    const items: React.ReactElement[] = [];

    Object.entries(links).forEach(([key, link]) => {
      items.push(
        renderLink(link.url, link.text, "nav-link")
      );
    });

    Object.entries(headerData).forEach(([key, item]) => {
      if (key !== 'links' && typeof item === 'object' && item.text && item.content) {
        const submenu = item as SubmenuItem;
        items.push(
          <div key={key} className="desktop-submenu">
            <button className="desktop-submenu-toggle">
              {submenu.text}
              <span className="submenu-arrow">▼</span>
            </button>
            <div className="desktop-submenu-content">
              {Object.entries(submenu.content).map(([linkKey, link]) => (
                renderLink(link.url, link.text, "desktop-submenu-link")
              ))}
            </div>
          </div>
        );
      }
    });

    return items;
  };

  const renderMobileLinks = () => {
    const headerData = navigation.header;
    const links = headerData.links || {};
    const items: React.ReactElement[] = [];

    Object.entries(links).forEach(([key, link]) => {
      items.push(
        renderLink(link.url, link.text, "nav-link", handleLinkClick)
      );
    });

    Object.entries(headerData).forEach(([key, item]) => {
      if (key !== 'links' && typeof item === 'object' && item.text && item.content) {
        const submenu = item as SubmenuItem;
        items.push(
          <div key={key} className="mobile-submenu">
            <button
              className="mobile-submenu-toggle"
              onClick={() => toggleSubmenu(key)}
            >
              {submenu.text}
              <span className={`submenu-arrow ${openSubmenu === key ? 'open' : ''}`}>
                ▼
              </span>
            </button>
            {openSubmenu === key && (
              <div className="mobile-submenu-content">
                {Object.entries(submenu.content).map(([linkKey, link]) => (
                  renderLink(link.url, link.text, "mobile-submenu-link", handleLinkClick)
                ))}
              </div>
            )}
          </div>
        );
      }
    });

    return items;
  };

  return (
    <header className="header">
      <div className="header-content">
        <div className="logo">
          <Link to="/" className="logo-link">
            <div className="logo-icon">
              <img src={logo40} alt="Logo" className="logo-image" style={{ width: '40px', height: '40px' }} />
            </div>
          </Link>
          <Link to="/" className="logo-link">
            <h1>Shrub Fund</h1>
          </Link>
        </div>
        
        {/* Desktop Navigation */}
        {!isMobile && (
          <nav className="desktop-nav">
            {renderDesktopLinks()}
          </nav>
        )}
        
        <div className="header-right">
          <WalletMultiButton />
          
          {/* Mobile Menu Button */}
          {isMobile && (
            <button 
              className="mobile-menu-button"
              onClick={toggleMobileMenu}
              aria-label="Toggle mobile menu"
            >
              <div className={`hamburger ${isMobileMenuOpen ? 'active' : ''}`}>
                <span></span>
                <span></span>
                <span></span>
              </div>
            </button>
          )}
        </div>
      </div>
      
      {/* Mobile Navigation */}
      {isMobile && (
        <nav className={`mobile-nav ${isMobileMenuOpen ? 'open' : ''}`}>
          <div className="mobile-nav-content">
            {renderMobileLinks()}
          </div>
        </nav>
      )}
    </header>
  );
};

export default Header;
