import React, { useState } from 'react';
import { Connection, PublicKey, Transaction, TransactionInstruction, SystemProgram } from '@solana/web3.js';
import { getAssociatedTokenAddressSync, TOKEN_PROGRAM_ID, createAssociatedTokenAccountInstruction } from '@solana/spl-token';
import { toast } from 'react-toastify';
import { formatDistanceToNow } from 'date-fns';
import { DISCRIMINATORS, PROGRAM_ID, USDC_MINT, FUND_POOL_PDA, PENDING_CASHOUT_POOL_PDA } from '../utils/constants';
import { UNLOCK_ICON } from '../utils/constants';
import { useStyling } from '../hooks/useStyling';

interface UnstakeTabProps {
  publicKey: PublicKey | null;
  connection: Connection;
  sendTransaction: any;
  userInfo: {
    shares: number;
    shareValue: number;
    canUnstake: boolean;
    stakeTimestamp: number;
    hasPendingUnstake: boolean;
    pendingUnstakeValue: number;
    unstakeInitiatedTimestamp: number;
    canCompleteUnstake: boolean;
    unstakeCompleteTime: number;
  };
  canUnstake: boolean;
  refreshUserData: () => Promise<void>;
}

const UnstakeTab: React.FC<UnstakeTabProps> = ({ 
  publicKey, 
  connection, 
  sendTransaction, 
  userInfo, 
  refreshUserData 
}) => {
  const styling = useStyling();
  const [isUnstaking, setIsUnstaking] = useState(false);
  const [isCompletingUnstake, setIsCompletingUnstake] = useState(false);

  const handleInitiateUnstake = async () => {
    if (!publicKey) return;

    setIsUnstaking(true);

    try {
      // Derive user share PDA, use constants for others to match existing deployment
      const [userSharePda] = PublicKey.findProgramAddressSync(
        [Buffer.from("user_share_v2"), publicKey.toBuffer()], 
        PROGRAM_ID
      );
      // Use existing deployed PDAs from constants
      const fundPoolPda = FUND_POOL_PDA;
      const pendingCashoutPoolPda = PENDING_CASHOUT_POOL_PDA;
      
      // Get user's registry info from their UserShare to derive the user_registry account
      const userShareData = await connection.getAccountInfo(userSharePda);
      if (!userShareData) {
        throw new Error('User has no shares to unstake');
      }
      
      const registryId = Number(userShareData.data.readBigUInt64LE(56));
      const registryIdBuffer = Buffer.alloc(8);
      registryIdBuffer.writeBigUInt64LE(BigInt(registryId), 0);
      const [userRegistryPda] = PublicKey.findProgramAddressSync(
        [Buffer.from("user_registry_v2"), registryIdBuffer], 
        PROGRAM_ID
      );
      
      const instructionData = Buffer.from(DISCRIMINATORS.initiate_unstake);

      const instruction = new TransactionInstruction({
        keys: [
          { pubkey: publicKey, isSigner: true, isWritable: true }, // user
          { pubkey: userSharePda, isSigner: false, isWritable: true }, // user_share
          { pubkey: fundPoolPda, isSigner: false, isWritable: true }, // fund_pool
          { pubkey: pendingCashoutPoolPda, isSigner: false, isWritable: true }, // pending_cashout_pool
          { pubkey: userRegistryPda, isSigner: false, isWritable: true }, // user_registry
          { pubkey: SystemProgram.programId, isSigner: false, isWritable: false }, // system_program
        ],
        programId: PROGRAM_ID,
        data: instructionData,
      });

      const transaction = new Transaction().add(instruction);
      const signature = await sendTransaction(transaction, connection);
      await connection.confirmTransaction(signature, 'confirmed');

      toast.success('Unstake initiated successfully!');
      await refreshUserData();
    } catch (error: any) {
      console.error('Initiate unstake failed:', error);
      toast.error(`Failed to initiate unstake: ${error.message}`);
    } finally {
      setIsUnstaking(false);
    }
  };

  const handleCompleteUnstake = async () => {
    if (!publicKey) return;

    setIsCompletingUnstake(true);

    try {
      // Derive user share PDA, use constants for others to match existing deployment  
      const [userSharePda] = PublicKey.findProgramAddressSync(
        [Buffer.from("user_share_v2"), publicKey.toBuffer()], 
        PROGRAM_ID
      );
      // Use existing deployed PDAs from constants
      const fundPoolPda = FUND_POOL_PDA;
      const pendingCashoutPoolPda = PENDING_CASHOUT_POOL_PDA;

      // Get token accounts
      const userUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, publicKey, false, TOKEN_PROGRAM_ID);
      const pendingCashoutUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, pendingCashoutPoolPda, true, TOKEN_PROGRAM_ID);

      // Get user's registry info from their UserShare to derive the user_registry account
      const userShareData = await connection.getAccountInfo(userSharePda);
      if (!userShareData) {
        throw new Error('User has no shares to complete unstake');
      }
      
      // Parse UserShare according to actual structure from lib.rs:
      // pub struct UserShare {
      //     pub user: Pubkey,                 // 32 bytes at offset 8
      //     pub shares: u64,                  // 8 bytes at offset 40
      //     pub stake_timestamp: i64,         // 8 bytes at offset 48
      //     pub registry_id: u64,             // 8 bytes at offset 56
      //     pub registry_index: u64,          // 8 bytes at offset 64
      //     pub unstake_initiated: bool,      // 1 byte at offset 72
      // }
      
      const registryId = Number(userShareData.data.readBigUInt64LE(56));
      const registryIndex = Number(userShareData.data.readBigUInt64LE(64));
      const unstakeInitiated = userShareData.data.length > 72 ? userShareData.data.readUInt8(72) !== 0 : false;
      
      if (!unstakeInitiated) {
        throw new Error('No unstake pending - must initiate unstake first');
      }
      
      const registryIdBuffer = Buffer.alloc(8);
      registryIdBuffer.writeBigUInt64LE(BigInt(registryId), 0);
      const [userRegistryPda] = PublicKey.findProgramAddressSync(
        [Buffer.from("user_registry_v2"), registryIdBuffer], 
        PROGRAM_ID
      );

      const transaction = new Transaction();

      // Check if user USDC account exists, create if not
      const userUsdcAccountInfo = await connection.getAccountInfo(userUsdcAta);
      if (!userUsdcAccountInfo) {
        transaction.add(
          createAssociatedTokenAccountInstruction(
            publicKey, userUsdcAta, publicKey, USDC_MINT
          )
        );
      }

      const instructionData = Buffer.from(DISCRIMINATORS.complete_unstake);

      const instruction = new TransactionInstruction({
        keys: [
          { pubkey: publicKey, isSigner: true, isWritable: true }, // user
          { pubkey: userUsdcAta, isSigner: false, isWritable: true }, // user_usdc_account
          { pubkey: userSharePda, isSigner: false, isWritable: true }, // user_share
          { pubkey: fundPoolPda, isSigner: false, isWritable: true }, // fund_pool
          { pubkey: pendingCashoutPoolPda, isSigner: false, isWritable: true }, // pending_cashout_pool
          { pubkey: pendingCashoutUsdcAta, isSigner: false, isWritable: true }, // pending_cashout_usdc_account
          { pubkey: userRegistryPda, isSigner: false, isWritable: true }, // user_registry
          { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false }, // token_program
          { pubkey: SystemProgram.programId, isSigner: false, isWritable: false }, // system_program
        ],
        programId: PROGRAM_ID,
        data: instructionData,
      });

      transaction.add(instruction);

      const signature = await sendTransaction(transaction, connection);
      await connection.confirmTransaction(signature, 'confirmed');

      toast.success('Unstake completed successfully!');
      await refreshUserData();
    } catch (error: any) {
      console.error('Complete unstake failed:', error);
      toast.error(`Failed to complete unstake: ${error.message}`);
    } finally {
      setIsCompletingUnstake(false);
    }
  };

  return (
    <>
      <h2>Unstake from Shrub Fund</h2>
      
      {publicKey && (
        <div className="balance-card">
          <div className="balance-row">
            <span>Your Fund Shares:</span>
            <span className="balance-value-green">{userInfo.shares.toFixed(2)}</span>
          </div>
          <div className="balance-row">
            <span>Share Value:</span>
            <span className="balance-value-green">${userInfo.shareValue.toFixed(2)}</span>
          </div>
          <div className="balance-row">
            <span>Can Unstake:</span>
            <span className={userInfo.canUnstake ? "balance-value-green" : "balance-value"}>{userInfo.canUnstake ? 'Yes' : 'No (7-day minimum)'}</span>
          </div>
          {userInfo.stakeTimestamp > 0 && (
            <div className="balance-row">
              <span>Staked Since:</span>
              <span>{formatDistanceToNow(new Date(userInfo.stakeTimestamp * 1000))} ago</span>
            </div>
          )}
          {userInfo.hasPendingUnstake && (
            <>
              <div className="balance-row">
                <span>Pending Unstake:</span>
                <span className="balance-value">${userInfo.pendingUnstakeValue.toFixed(2)}</span>
              </div>
              {userInfo.unstakeInitiatedTimestamp > 0 && (
                <div className="balance-row">
                  <span>Unstake Initiated:</span>
                  <span>{formatDistanceToNow(new Date(userInfo.unstakeInitiatedTimestamp * 1000))} ago</span>
                </div>
              )}
              {userInfo.unstakeCompleteTime > 0 && (
                <div className="balance-row">
                  <span>Can Complete At:</span>
                  <span className={userInfo.canCompleteUnstake ? "balance-value-green" : "balance-value"}>
                    {new Date(userInfo.unstakeCompleteTime * 1000).toLocaleString()}
                  </span>
                </div>
              )}
              {!userInfo.canCompleteUnstake && userInfo.unstakeCompleteTime > 0 && (
                <div className="balance-row">
                  <span>Time Remaining:</span>
                  <span className="balance-value">
                    {formatDistanceToNow(new Date(userInfo.unstakeCompleteTime * 1000))}
                  </span>
                </div>
              )}
            </>
          )}
        </div>
      )}

      <div className="form-section">
        {!userInfo.hasPendingUnstake ? (
          <button
            onClick={handleInitiateUnstake}
            disabled={!publicKey || isUnstaking || !userInfo.canUnstake || userInfo.shares <= 0}
            className="contribute-button"
            style={styling.createStyle({ 
              background: userInfo.canUnstake && userInfo.shares > 0
                ? '$colors.secondary.orangeGradient'
                : '$colors.secondary.grayGradient'
            })}
          >
            {isUnstaking ? (
              <div className="spinner" />
            ) : (
              <>
                <span style={styling.createStyle({ fontSize: '$fontSize.md' })}>{UNLOCK_ICON}</span>
                <span>Initiate Unstake (All Shares)</span>
              </>
            )}
          </button>
        ) : (
          <button
            onClick={handleCompleteUnstake}
            disabled={!publicKey || isCompletingUnstake || !userInfo.canCompleteUnstake}
            className="contribute-button"
            style={styling.createStyle({ 
              background: userInfo.canCompleteUnstake
                ? '$colors.secondary.redGradient'
                : '$colors.secondary.grayGradient'
            })}
          >
            {isCompletingUnstake ? (
              <div className="spinner" />
            ) : (
              <>
                <span style={styling.createStyle({ fontSize: '$fontSize.md' })}>{UNLOCK_ICON}</span>
                <span>
                  {userInfo.canCompleteUnstake 
                    ? 'Complete Unstake (Receive USDC)'
                    : 'Complete Unstake (7-day period required)'
                  }
                </span>
              </>
            )}
          </button>
        )}
      </div>

      {!userInfo.canUnstake && userInfo.shares > 0 && (
        <div style={styling.createStyle({
          padding: '$spacing.md',
          background: 'rgba(245, 158, 11, 0.1)',
          border: '1px solid rgba(245, 158, 11, 0.3)',
          borderRadius: '$borderRadius.md',
          color: '$colors.status.warning',
          fontSize: '$fontSize.sm',
          textAlign: 'center'
        })}>
          ⏰ 7-day minimum holding period required before unstaking
        </div>
      )}
    </>
  );
};

export default UnstakeTab;