// src/hooks/useGardenerData.ts (similar for gardener)
import { useState, useEffect } from 'react';
import { getAssociatedTokenAddressSync } from '@solana/spl-token';
import { toast } from 'react-toastify';
import {
  GARDENER_WALLET,
  USDC_MINT,
  FUND_POOL_PDA,
  PENDING_CASHOUT_POOL_PDA,
  REGISTRY_DIRECTORY_PDA,
  TRADING_WALLET,
  NAV_HISTORY_PDA,
  TOKEN_PROGRAM_ID
} from '../utils/constants';

const useGardenerData = (publicKey: any, connection: any, activeTab: string) => {
  const [gardenerData, setGardenerData] = useState({
    isGardener: false,
    pendingCashoutAmount: 0,
    pendingCashoutPoolBalance: 0,
    registryHealth: { totalUserRegistries: 0, totalActiveUsers: 0, totalPendingUnstakes: 0 },
    tradingWalletBalance: 0,
    realNav: 0,
    totalShares: 0,
    pdaSolBalances: { fundPool: 0, navHistory: 0, pendingCashoutPool: 0, registryDirectory: 0 }
  });
  const [loadingGardenerData, setLoadingGardenerData] = useState(false);

  const refreshGardenerData = async () => {
    if (!publicKey || !connection) {
      setGardenerData(prev => ({ ...prev, isGardener: false }));
      return;
    }

    setLoadingGardenerData(true);
    try {
      // Check if user is gardener (either gardener wallet or trading wallet)
      const isGardener = publicKey.equals(GARDENER_WALLET) || publicKey.equals(TRADING_WALLET);
      
      if (!isGardener) {
        setGardenerData(prev => ({ ...prev, isGardener: false }));
        setLoadingGardenerData(false);
        return;
      }
      
      // Fetch fund pool for pending cashout
      const fundPoolInfo = await connection.getAccountInfo(FUND_POOL_PDA);
      let pendingCashoutAmount = 0;
      if (fundPoolInfo && fundPoolInfo.data.length >= 81) {
        pendingCashoutAmount = Number(fundPoolInfo.data.readBigUInt64LE(40)) / 1_000_000;
      }
      
      // Fetch pending cashout pool USDC balance
      let pendingCashoutPoolBalance = 0;
      try {
        const pendingCashoutUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, PENDING_CASHOUT_POOL_PDA, true, TOKEN_PROGRAM_ID);
        const balance = await connection.getTokenAccountBalance(pendingCashoutUsdcAta);
        pendingCashoutPoolBalance = balance.value.uiAmount || 0;
      } catch (error) {
        console.error('Error fetching cashout pool balance:', error);
      }
      
      // Fetch registry directory health
      const registryDirectoryInfo = await connection.getAccountInfo(REGISTRY_DIRECTORY_PDA);
      let registryHealth = { totalUserRegistries: 0, totalActiveUsers: 0, totalPendingUnstakes: 0 };
      if (registryDirectoryInfo && registryDirectoryInfo.data.length >= 16) {
        const data = registryDirectoryInfo.data;
        registryHealth.totalUserRegistries = Number(data.readBigUInt64LE(8));  // total_registries
        registryHealth.totalActiveUsers = Number(data.readBigUInt64LE(16));    // active_users
      }

      // For now, we'll estimate pending unstakes based on whether there's a pending amount
      // TODO: Properly parse PendingCashoutPool structure to get exact count
      registryHealth.totalPendingUnstakes = pendingCashoutAmount > 0 ? 1 : 0; // Placeholder - needs proper implementation
      
      // Fetch trading wallet USDC balance
      let tradingWalletBalance = 0;
      try {
        const tradingUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, TRADING_WALLET, false, TOKEN_PROGRAM_ID);
        const balance = await connection.getTokenAccountBalance(tradingUsdcAta);
        tradingWalletBalance = balance.value.uiAmount || 0;
      } catch (error) {
        console.error('Error fetching trading wallet balance:', error);
      }
      
      // Fetch real NAV and total shares from fund pool
      let realNav = 1000000; // In USDC units (1 USDC = 1,000,000 units)
      let totalShares = 0;
      if (fundPoolInfo && fundPoolInfo.data.length >= 81) {
        const data = fundPoolInfo.data;
        totalShares = Number(data.readBigUInt64LE(8)) / 1_000_000; // Convert from units to USDC
        realNav = Number(data.readBigUInt64LE(24)) / 1_000_000; // This is total fund value, not per-share
      }
      
      // Fetch PDA SOL balances
      const pdaSolBalances = {
        fundPool: (await connection.getBalance(FUND_POOL_PDA)) / 1_000_000_000,
        navHistory: (await connection.getBalance(NAV_HISTORY_PDA)) / 1_000_000_000,
        pendingCashoutPool: (await connection.getBalance(PENDING_CASHOUT_POOL_PDA)) / 1_000_000_000,
        registryDirectory: (await connection.getBalance(REGISTRY_DIRECTORY_PDA)) / 1_000_000_000,
      };
      
      setGardenerData({
        isGardener: true,
        pendingCashoutAmount,
        pendingCashoutPoolBalance,
        registryHealth,
        tradingWalletBalance,
        realNav,
        totalShares,
        pdaSolBalances
      });
    } catch (error) {
      console.error('Error fetching gardener data:', error);
      toast.error('Failed to fetch gardener dashboard data');
    } finally {
      setLoadingGardenerData(false);
    }
  };

  useEffect(() => {
    if ((activeTab !== 'fund' && activeTab !== 'shrub-stakes') || !publicKey || !connection) return;
    refreshGardenerData();
  }, [publicKey, connection, activeTab]);

  return { gardenerData, loadingGardenerData, refreshGardenerData };
};

export default useGardenerData;