// src/hooks/useProtocolStats.ts (custom hook for fetching protocol stats)
import { useState, useEffect } from 'react';
import { Connection, PublicKey } from '@solana/web3.js';
import { getAssociatedTokenAddressSync, TOKEN_PROGRAM_ID } from '@solana/spl-token';
import { FUND_POOL_PDA, USDC_MINT, TRADING_WALLET } from '../utils/constants';
import { toast } from 'react-toastify';

interface ProtocolStats {
  totalFundValue: number;
  totalShares: number;
  nav: number;
  realNav: number;
}

const useProtocolStats = (activeTab: string, connection: Connection | null) => {
  const [stats, setStats] = useState<ProtocolStats>({ totalFundValue: 0, totalShares: 0, nav: 1.0, realNav: 1.0 });
  const [loadingStats, setLoadingStats] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if ((activeTab !== 'fund' && activeTab !== 'shrub-stakes') || !connection) return;
    
    const fetchProtocolStats = async () => {
      setLoadingStats(true);
      setError(null);
      try {
        // Get fund pool data
        const fundPoolInfo = await connection.getAccountInfo(FUND_POOL_PDA);
        
        let totalShares = 0;
        let totalFundValue = 0;
        let nav = 1.0;
        let realNav = 1.0;

        if (fundPoolInfo && fundPoolInfo.data.length >= 81) {
          const data = fundPoolInfo.data;
          // Current FundPool v2 structure (after 8-byte discriminator):
          // total_shares: u64,        // offset 8
          // optimized_nav: u64,       // offset 16  
          // real_nav: u64,            // offset 24
          // total_users: u64,         // offset 32
          // pending_cashout: u64,     // offset 40
          // authority: Pubkey,        // offset 48 (32 bytes)
          // bump: u8,                 // offset 80
          
          totalShares = Number(data.readBigUInt64LE(8)); // Total shares in raw units
          const optimizedNavRaw = Number(data.readBigUInt64LE(16)); // NAV total in USDC units (6 decimals)
          const realNavRaw = Number(data.readBigUInt64LE(24)); // Real NAV total in USDC units (6 decimals)
          
          // The optimizedNavRaw should be the total fund value in USDC units
          totalFundValue = optimizedNavRaw / 1_000_000; // Convert to actual USDC
          
          // Calculate shares in proper units (likely also need USDC conversion)
          const totalSharesInUsdc = totalShares / 1_000_000;
          nav = totalSharesInUsdc > 0 ? totalFundValue / totalSharesInUsdc : 1.0;
          
          // Calculate real NAV for staking calculations
          const realFundValue = realNavRaw / 1_000_000; // Convert to actual USDC
          realNav = totalSharesInUsdc > 0 ? realFundValue / totalSharesInUsdc : 1.0;
        }

        // Get trading wallet USDC balance as current fund value verification
        let tradingValue = 0;
        try {
          const tradingUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, TRADING_WALLET, false, TOKEN_PROGRAM_ID);
          const tradingBalance = await connection.getTokenAccountBalance(tradingUsdcAta).catch(() => ({ value: { uiAmount: 0 } }));
          tradingValue = tradingBalance.value.uiAmount || 0;
        } catch (error: any) {
          console.error('Error fetching trading wallet balance:', error);
        }

        console.log('📊 Fund Stats:', {
          totalFundValue: totalFundValue.toFixed(2),
          totalShares: totalShares.toFixed(2),
          nav: nav.toFixed(4),
          tradingValue: tradingValue.toFixed(2)
        });
        
        setStats({
          totalFundValue,
          totalShares: totalShares / 1_000_000, // Store as converted value for display
          nav,
          realNav
        });
        
      } catch (error) {
        console.error('Error fetching protocol stats:', error);
        setError('Failed to fetch stats');
        toast.error('Error fetching protocol stats');
        setStats({
          totalFundValue: 0,
          totalShares: 0,
          nav: 1.0,
          realNav: 1.0
        });
      } finally {
        setLoadingStats(false);
      }
    };

    fetchProtocolStats();
  }, [activeTab, connection]);

  return { stats, loadingStats, error };
};

export default useProtocolStats;